function.arguments:
{"sql": "SELECT DISTINCT ms.name, ms.version
FROM model_score ms
WHERE ms.step IN (1, 2, 3)
  AND (
    SELECT MAX(test_score) FROM model_score ms2
    WHERE ms2.name = ms.name AND ms2.version = ms.version AND ms2.step = ms.step AND ms2.model != 'Stack'
  ) < (
    SELECT test_score FROM model_score ms3
    WHERE ms3.name = ms.name AND ms3.version = ms.version AND ms3.step = ms.step AND ms3.model = 'Stack'
  )"}
